I have also another example which doesn't work:

```
export interface LongpressOptions {
	stopEvent: boolean
	multiObservers: boolean
	multiEmit: boolean
	multiTimeout: number
}

@Directive({
	selector: '[longpress]',
	standalone: true,
})
export class LongpressDirective {
	@Input({
		alias: 'longpress',
		transform: (obj: Record<keyof LongpressOptions, unknown>) => {
			obj.stopEvent = obj.stopEvent ?? true
			obj.multiObservers = obj.multiObservers ?? false
			obj.multiEmit = obj.multiEmit ?? false
			obj.multiTimeout = obj.multiTimeout ?? LONGPRESS_DELAY
		}
	})
	public options!: LongpressOptions
```
